"""ATHBA initial production module."""


class ShoppingBasket:
    """Represents a shopping basket for items."""

    def __init__(self):
        self.items = {}

    def add_item(self, item_id, quantity=1, price=0):
        """Add an item to the basket."""
        if item_id in self.items:
            self.items[item_id]["quantity"] += quantity
        else:
            self.items[item_id] = {"quantity": quantity, "price": price}

    def total(self):
        """Calculate total price of basket."""
        return sum(item["quantity"] * item["price"] for item in self.items.values())

    def total_price(self):
        """Calculate total price of basket."""
        return self.total()

    def item_count(self):
        """Return the number of unique items in the basket."""
        return len(self.items)

    def items_dict(self):
        """Return items as a dictionary."""
        return self.items

